CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT UNIQUE NOT NULL
);

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * migrate.js
 *
 * Reads all .sql files from the ./migrations/ directory, sorts them
 * alphabetically (so numeric prefixes determine order), and logs each
 * filename that would be applied, in order.
 */
function migrate() {
  // Ensure the migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  // Read all entries and filter to .sql files
  const files = fs.readdirSync(MIGRATIONS_DIR)
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort(); // Lexicographic sort ensures numbered prefixes are in order

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration(s) to apply:\n`);

  files.forEach((file, index) => {
    console.log(`  ${index + 1}. Applying: ${file}`);
  });

  console.log('\nAll migrations listed successfully.');
}

migrate();

