#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * migrate.js
 *
 * Reads DATABASE_URL from .env.test, resolves the connection string,
 * then reads all .sql files from the ./migrations/ directory, sorts them
 * alphabetically (so numeric prefixes determine order), and logs each
 * filename that would be applied, in order.
 */

/**
 * Parses a .env-style file and returns an object of key-value pairs.
 * Supports comments (#), empty lines, and optional quoting of values.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exit(1);
  }

  const contents = fs.readFileSync(filePath, 'utf-8');
  const env = {};

  contents.split('\n').forEach(line => {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;

    const match = trimmed.match(/^([^=]+?)\s*=\s*(.*)?$/);
    if (match) {
      const key = match[1].trim();
      let value = (match[2] || '').trim();

      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      env[key] = value;
    }
  });

  return env;
}

/**
 * Resolves the DATABASE_URL from .env.test and logs a connection message.
 */
function resolveConnection() {
  console.log(`Reading connection string from ${path.basename(ENV_FILE)}...\n`);

  const env = parseEnvFile(ENV_FILE);
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('DATABASE_URL is not defined in .env.test');
    process.exit(1);
  }

  // Mask the password in the URL for safe logging
  let displayUrl;
  try {
    const parsed = new URL(databaseUrl);
    if (parsed.password) {
      parsed.password = '****';
    }
    displayUrl = parsed.toString();
  } catch {
    displayUrl = databaseUrl;
  }

  console.log(`Connected successfully to database: ${displayUrl}\n`);

  return databaseUrl;
}

function migrate() {
  // Resolve database connection string
  resolveConnection();

  // Ensure the migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  // Read all entries and filter to .sql files
  const files = fs.readdirSync(MIGRATIONS_DIR)
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort(); // Lexicographic sort ensures numbered prefixes are in order

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration(s) to apply:\n`);

  files.forEach((file, index) => {
    console.log(`  ${index + 1}. Applying: ${file}`);
  });

  console.log('\nAll migrations listed successfully.');
}

