/**
 * Parses a .env-style file and returns an object of key-value pairs.
 * Supports lines in the format KEY=VALUE (with optional quoting).
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exit(1);
  }

  const contents = fs.readFileSync(filePath, 'utf-8');
  const env = {};

  for (const line of contents.split('\n')) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    let value = trimmed.slice(eqIndex + 1).trim();

    // Remove surrounding quotes if present
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

/**
 * Resolves the DATABASE_URL from the .env.test file.
 * Logs a success message (does not actually connect).
